import subprocess,json
from concurrent.futures import ThreadPoolExecutor
commands=[['df','-h','/scratch/e1583364','/home/svu/e1583364'],['du','-h','--max-depth=1','/scratch/e1583364/cvpr2027'],['du','-h','--max-depth=1','/scratch/e1583364']]
def run(command):
 try:
  p=subprocess.run(command,text=True,capture_output=True,timeout=50)
  return {'command':command,'exit_code':p.returncode,'stdout':p.stdout,'stderr':p.stderr}
 except subprocess.TimeoutExpired as e:
  return {'command':command,'timed_out':True,'stdout':(e.stdout or b'').decode() if isinstance(e.stdout,bytes) else e.stdout,'stderr':(e.stderr or b'').decode() if isinstance(e.stderr,bytes) else e.stderr}
for result in ThreadPoolExecutor(max_workers=2).map(run,commands):print(json.dumps(result),flush=True)

